#include <iostream>

int main() {
    // 测试输入留空。输出：第 1 格到第 4 格的值，以及总和 100。
    int values[4] = {10, 20, 30, 40};
    int total = 0;
    for (int i = 0; i < 4; ++i) {
        std::cout << values[i] << '\n';
        total = total + values[i];
    }
    std::cout << "总和：" << total << '\n';
    return 0;
}
